package com.cartogenesis.cartography

/**
 * A 32x32 world, gzipped by the JVM's own gzip algorithm (see [GzipInteroperabilityTest]),
 * checked in as base64 chunks because a single Kotlin string literal this size trips the
 * JVM class file's 64KB-per-constant limit. Carries all 31 sections WorldSections.of
 * writes as of B2 (the per-cell crust-pair boundary class) - regenerate via a throwaway
 * jvmTest if that count changes again. Since D4 a container missing a section no longer
 * fails to open, it regenerates the stage that section belonged to, so a stale fixture
 * would quietly stop testing what it was written to test.
 */
internal val GZIP_FIXTURE_BASE64: String =
    "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        ""
